from pathlib import Path
root=Path(__file__).resolve().parent
src=root.parent/'embedding_submission'
core=(src/'embedding_core.py').read_text()
(root/'embedding_core.py').write_text(core)
s=(src/'submit_pipeline.py').read_text()
s=s.replace("VERSION='embedding-submission-v1'","VERSION='embedding-deadline-v2'")
s=s.replace("assert meta['candidate_k']==20 and meta['ann_nprobe']==64 and meta['ann_overfetch']==200", "assert meta['candidate_k']==20 and (meta['ann_nprobe'],meta['ann_overfetch']) in [(64,200),(128,400)]")
s=s.replace("return bundle,meta", "bundle['ann_nprobe']=meta['ann_nprobe'];bundle['ann_overfetch']=meta['ann_overfetch']\n    return bundle,meta",1)
s=s.replace("'candidate_k':20,'nprobe':64,'overfetch':200", "'candidate_k':20,'nprobe':meta['ann_nprobe'],'overfetch':meta['ann_overfetch']")
s=s.replace("; 20 candidates; 64 cells / 200 intermediate neighbors", "; 20 candidates; {meta['ann_nprobe']} cells / {meta['ann_overfetch']} intermediate neighbors")
s=s.replace('def __init__(self,work):','def __init__(self,work,nprobe=64,overfetch=200):')
s=s.replace('self.work=work;self.faiss=faiss','self.work=work;self.faiss=faiss;self.overfetch=overfetch')
s=s.replace('index.nprobe=min(64,index.nlist)','index.nprobe=min(nprobe,index.nlist)')
s=s.replace('dtype=np.float32),200)','dtype=np.float32),self.overfetch)')
s=s.replace('searcher=TestSearcher(work)','searcher=TestSearcher(work,bundle.get("ann_nprobe",64),bundle.get("ann_overfetch",200))')
s=s.replace("work.parent/'embedding_submission_v1_backup.zip'", "work.parent/'embedding_submission_v2_backup.zip'")
s=s.replace('Embedding submission v1','Embedding submission v2').replace('embedding submission v1','embedding submission v2')
s=s.replace('Training targets include the entire provided train S2/S3 pool.', 'Training targets include the entire provided train S2/S3 pool.')
s=s.replace('with 500 tuning and 500 evaluation businesses.', 'with 2000 tuning and 2000 fresh evaluation businesses.')
s=s.replace('It was trained on 3000 sampled S1 businesses (60000 pairs),','It was trained on 30000 sampled S1 businesses (up to 600000 pairs),')
s=s.replace('Search probes 64 cells, retrieves up to 200 approximate candidates,', "Search probes {meta['ann_nprobe']} cells, retrieves up to {meta['ann_overfetch']} approximate candidates,")
s=s.replace('The trained matcher in `model/matcher.pkl` comes from that experiment, not test labels.', 'The trained matcher in `model/matcher.pkl` comes from that experiment, not test labels.\nThe upgrade training notebook requires the v1 training caches as a read-only input.')
(root/'submit_pipeline.py').write_text(s)
